import type { TaskPriority } from '../services/task/requestModel';

export interface PriorityPrefill {
  priority: TaskPriority;
  dueDate: string;
}

function addHours(base: Date, hours: number): string {
  return new Date(base.getTime() + hours * 60 * 60 * 1000).toISOString();
}

function addDays(base: Date, days: number): string {
  return new Date(base.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
}

/** Patrol session footer default (GAP-RTI-PATROL-02 · SA §5A). */
export function patrolSessionPrefill(route: string): PriorityPrefill & { title: string } {
  const now = new Date();
  return {
    title: `Xử lý điểm Cấp bách — ${route || 'Tuần tra'}`,
    priority: 'high',
    dueDate: addHours(now, 48),
  };
}

/** Incident severity → priority + dueDate (SA §5B). */
export function incidentSeverityPrefill(severity: string): PriorityPrefill | null {
  const now = new Date();
  switch (severity) {
    case 'critical':
      return { priority: 'critical', dueDate: addHours(now, 24) };
    case 'high':
      return { priority: 'high', dueDate: addHours(now, 48) };
    case 'medium':
      return { priority: 'medium', dueDate: addDays(now, 7) };
    case 'low':
      return { priority: 'low', dueDate: addDays(now, 14) };
    default:
      return { priority: 'medium', dueDate: addDays(now, 7) };
  }
}

export function canSuggestTaskFromIncident(severity: string, status: string): boolean {
  if (status === 'closed') return false;
  return severity !== 'low';
}
