import React, { useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Button } from '@linm-soft-org/linm-web-common-components';
import { ChatSectionHost } from '../ChatSectionHost/ChatSectionHost';
import type { DomainSource } from '../../services/task/requestModel';
import { platformTaskDetailHref } from '../../utils/platformTaskUrls';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import styles from './TaskChatPanel.module.css';

export interface TaskChatTarget {
  taskId: string;
  from: DomainSource;
  sourceId: string;
  title?: string;
}

export interface TaskChatPanelProps {
  target: TaskChatTarget | null;
  onClose: () => void;
}

export const TaskChatPanel: React.FC<TaskChatPanelProps> = ({ target, onClose }) => {
  const navigate = useInAppNavigate();

  const onParcelNavigate = useCallback(
    (path: string) => {
      if (/^https?:\/\//i.test(path)) {
        window.location.assign(path);
        return;
      }
      navigate(path);
    },
    [navigate],
  );

  if (!target) return null;

  const taskHref = platformTaskDetailHref(target.taskId, target.from, target.sourceId);

  return createPortal(
    <div
      className={styles.overlay}
      data-testid="field-task-chat-overlay"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className={styles.panel} role="dialog" aria-modal="true" aria-labelledby="field-task-chat-title">
        <div className={styles.header}>
          <h2 id="field-task-chat-title">Trao đổi công việc</h2>
          <div className={styles.actions}>
            <Button
              variant="secondary"
              size="sm"
              onClick={() => {
                if (/^https?:\/\//i.test(taskHref)) window.location.assign(taskHref);
                else navigate(taskHref);
              }}
              data-testid="field-task-chat-open-task"
            >
              <i className="fas fa-external-link-alt" /> Mở Task MFE
            </Button>
            <Button variant="secondary" size="sm" onClick={onClose} data-testid="field-task-chat-close">
              Đóng
            </Button>
          </div>
        </div>
        {target.title ? <p className={styles.sub}>{target.title}</p> : null}
        <ChatSectionHost taskId={target.taskId} onNavigate={onParcelNavigate} />
      </div>
    </div>,
    document.body,
  );
};

export default TaskChatPanel;
